CREATE TABLE IF NOT EXISTS instances (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, software TEXT NOT NULL, software_version TEXT, minecraft_version TEXT NOT NULL, build TEXT, path TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'offline', min_memory_mb INTEGER NOT NULL, max_memory_mb INTEGER NOT NULL, host TEXT NOT NULL, port INTEGER NOT NULL, java_major INTEGER NOT NULL, runtime_id TEXT, pid INTEGER, favorite INTEGER NOT NULL DEFAULT 0, restart_required INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runtimes (id TEXT PRIMARY KEY, java_major INTEGER NOT NULL, os TEXT NOT NULL, arch TEXT NOT NULL, path TEXT NOT NULL UNIQUE, version TEXT NOT NULL, checksum TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS installed_plugins (id TEXT PRIMARY KEY, instance_id TEXT NOT NULL, provider TEXT, project_id TEXT, version_id TEXT, name TEXT NOT NULL, file_name TEXT NOT NULL, managed INTEGER NOT NULL DEFAULT 0, previous_file TEXT, installed_at TEXT NOT NULL, FOREIGN KEY(instance_id) REFERENCES instances(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS plugin_sources (id TEXT PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 1, settings_json TEXT);
CREATE TABLE IF NOT EXISTS backups (id TEXT PRIMARY KEY, instance_id TEXT NOT NULL, path TEXT NOT NULL, name TEXT NOT NULL, size INTEGER NOT NULL, description TEXT, automatic INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, FOREIGN KEY(instance_id) REFERENCES instances(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS scheduled_tasks (id TEXT PRIMARY KEY, instance_id TEXT NOT NULL, name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, cron TEXT NOT NULL, action TEXT NOT NULL, payload_json TEXT, last_run TEXT, next_run TEXT, last_result TEXT, FOREIGN KEY(instance_id) REFERENCES instances(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS activity_events (id TEXT PRIMARY KEY, instance_id TEXT, type TEXT NOT NULL, message TEXT NOT NULL, details_json TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS process_state (instance_id TEXT PRIMARY KEY, pid INTEGER, status TEXT NOT NULL, started_at TEXT, stopped_at TEXT, exit_code INTEGER, crash_json TEXT);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stats_history (id TEXT PRIMARY KEY, instance_id TEXT NOT NULL, sampled_at TEXT NOT NULL, server_cpu REAL, server_memory INTEGER, players INTEGER, host_cpu REAL, host_memory INTEGER, host_memory_total INTEGER, FOREIGN KEY(instance_id) REFERENCES instances(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_activity_instance_created ON activity_events(instance_id, created_at);
CREATE INDEX IF NOT EXISTS idx_plugins_instance ON installed_plugins(instance_id);
CREATE INDEX IF NOT EXISTS idx_backups_instance_created ON backups(instance_id, created_at);
CREATE INDEX IF NOT EXISTS idx_stats_instance_sampled ON stats_history(instance_id, sampled_at);
CREATE TABLE IF NOT EXISTS networks (id TEXT PRIMARY KEY, name TEXT NOT NULL, minecraft_version TEXT NOT NULL, proxy_instance_id TEXT NOT NULL, service_token_hash TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(proxy_instance_id) REFERENCES instances(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS network_members (id TEXT PRIMARY KEY, network_id TEXT NOT NULL, instance_id TEXT NOT NULL, role TEXT NOT NULL, alias TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(network_id) REFERENCES networks(id) ON DELETE CASCADE, FOREIGN KEY(instance_id) REFERENCES instances(id) ON DELETE CASCADE, UNIQUE(network_id, alias));
CREATE INDEX IF NOT EXISTS idx_network_members_network ON network_members(network_id, role, priority);
CREATE TABLE IF NOT EXISTS player_mode_locations (id TEXT PRIMARY KEY, network_id TEXT NOT NULL, player_uuid TEXT NOT NULL, player_name TEXT NOT NULL, mode_id TEXT NOT NULL, realm_id TEXT NOT NULL, server_alias TEXT NOT NULL, world_key TEXT NOT NULL, x REAL NOT NULL, y REAL NOT NULL, z REAL NOT NULL, yaw REAL NOT NULL, pitch REAL NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(network_id) REFERENCES networks(id) ON DELETE CASCADE, UNIQUE(network_id, player_uuid, mode_id));
CREATE INDEX IF NOT EXISTS idx_player_mode_locations_lookup ON player_mode_locations(network_id, player_uuid, mode_id, updated_at);
CREATE TABLE IF NOT EXISTS player_mode_profiles (id TEXT PRIMARY KEY, network_id TEXT NOT NULL, player_uuid TEXT NOT NULL, player_name TEXT NOT NULL, mode_id TEXT NOT NULL, profile_json TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(network_id) REFERENCES networks(id) ON DELETE CASCADE, UNIQUE(network_id, player_uuid, mode_id));
CREATE INDEX IF NOT EXISTS idx_player_mode_profiles_lookup ON player_mode_profiles(network_id, player_uuid, mode_id, updated_at);
CREATE TABLE IF NOT EXISTS network_moderation_events (sequence INTEGER PRIMARY KEY AUTOINCREMENT, network_id TEXT NOT NULL, event_key TEXT NOT NULL, source_alias TEXT NOT NULL, event_json TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(network_id) REFERENCES networks(id) ON DELETE CASCADE, UNIQUE(network_id, event_key));
CREATE INDEX IF NOT EXISTS idx_network_moderation_events_sequence ON network_moderation_events(network_id, sequence);
